/* Qwark on Rilgar: check its regions, wait for the hero to enter region A, then react. */
void qwark_rilgar_update(char *m)
{
    enum {
        QWARK_RILGAR_INITIALIZE = 0,
        QWARK_RILGAR_WAIT_FOR_PLAYER_IN_REGION = 1,
        QWARK_RILGAR_POST_REGION_TRIGGER = 2
    };
    Moby *moby = (Moby *)m;
    QwarkWatchData *watch_data;
    float rate;
    float head_rate;
    int tracking;
    float s_target[4];
    float s_eye[4];
    float s_delta[4];

    watch_data = (QwarkWatchData *)moby->pvars;
    attach_cutscene_fixed_scale_manipulator_m(m);
    if (moby->visible != 0) {
        if (FastVecDist_r2(&moby->pos, kerwan_camera_pos) < 30.0f) {
            set_ground_height_band(m);
            moby->shadow_range = 0x18;
        }
    }
    switch (moby->state) {
    case QWARK_RILGAR_INITIALIZE:
        moby->update_dist = 0xFF;
        if (watch_data->region_a == -1)
            STUB_printf(qwark_rilgar_no_region_a_msg);
        if (watch_data->region_c == -1)
            STUB_printf(qwark_rilgar_no_region_c_msg);
        if (watch_data->region_b == -1) {
            STUB_printf(qwark_rilgar_no_region_b_msg);
        } else if (kerwan_mobys_r[watch_data->region_b].state != 0) {
            if (watch_data->region_c != -1)
                kerwan_mobys_r[watch_data->region_c].state = 3;
            DeleteMoby(m);
            return;
        }
        moby->state = 1;
        break;
    case QWARK_RILGAR_WAIT_FOR_PLAYER_IN_REGION:
        if (watch_data->region_a != -1 &&
            is_point_inside_clip_volume_r2(&hero.motion.pos, watch_data->region_a)) {
            set_moby_dialogue_record_value(m, 1);
            moby->state = 2;
        }
        break;
    case QWARK_RILGAR_POST_REGION_TRIGGER:
        moby->state = 3;
        break;
    }
    rate = 0.02f;
    head_rate = 0.3f;
    tracking = 0;
    if (moby->prev_seq == 0) {
        tracking = 1;
        if (vec_distance_xy_r2(&moby->pos, &hero.motion.pos) < 8.0f &&
            FastDiffRots(moby->rot.z,
                fast_atan2(hero.motion.body_center.f[0] - moby->pos.x,
                                  hero.motion.body_center.f[1] - moby->pos.y)) < 1.5707964f) {
            if (FastVecLength(&hero.motion.displacement) > 0.01f)
                watch_data->moving_timer = scale_ticks(120);
            else
                fast_dec_timer(&watch_data->moving_timer);
        } else if (watch_data->moving_timer != 0) {
            watch_data->moving_timer = 0;
            qcopy(&watch_data->target, &hero.motion.body_center);
        }
        if (fast_dec_timer(&watch_data->target_timer)) {
            float heading;
            watch_data->target_timer = truncate_float_to_s32_r(multiply_global_factor(random_float_between(180.0f, 300.0f)));
            heading = FastAddRots(moby->rot.z, random_float_between(-90.0f, 90.0f) * 0.017453292f);
            BuildSphericalOffset(&watch_data->target, 6.0f, heading,
                                 random_float_between(0.0f, 30.0f) * 0.017453292f);
            FastVecAdd(&watch_data->target, &watch_data->target, &moby->pos);
        }
        if (watch_data->moving_timer != 0) {
            qcopy(s_target, &hero.motion.body_center);
            rate = 0.04f;
            head_rate = 0.3f;
        } else {
            qcopy(s_target, &watch_data->target);
        }
    }
    if (tracking) {
        float yaw;
        float pitch;
        qcopy(s_eye, &moby->pos);
        s_eye[2] += 1.0f;
        FastVecSub(s_delta, s_target, s_eye);
        yaw = FastSubRots(fast_atan2(s_delta[0], s_delta[1]), moby->rot.z);
        pitch = -fast_atan2(vec_length_xy(s_delta), s_delta[2]);
        if (yaw > 1.5707964f)
            yaw = 1.5707964f;
        else if (yaw < -1.5707964f)
            yaw = -1.5707964f;
        if (pitch > 0.5235988f)
            pitch = 0.5235988f;
        else if (pitch < -0.5235988f)
            pitch = -0.5235988f;
        watch_data->pitch = pitch;
        watch_data->yaw = yaw * 0.6f;
        watch_data->head_yaw = yaw * 0.4f;
    }
    if (gCheats[0] != 0)
        watch_data->height = 2.75f;
    EaseManipulatorOffsets(m, (char *)watch_data, 0, rate * g_frame_scale_sq, head_rate * g_frame_scale_sq);
    EaseManipulatorOffsets(m, (char *)watch_data + 0x80, 1, rate * g_frame_scale_sq, head_rate * g_frame_scale_sq);
}
