    ((Moby *)moby)->rot.y = FastAddRots(((Moby *)moby)->rot.y, *(float *)(d + 0x14));
    ((Moby *)moby)->rot.z = FastAddRots(((Moby *)moby)->rot.z, *(float *)(d + 0x18));
